program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Horizontal bands repeat according to their row positions modulo band count.
    bands = {}
    horizontal = True
    for r, row in enumerate(grid):
        nz = {v for v in row if v}
        if nz:
            if len(nz) != 1 or any(v == 0 for v in row):
                horizontal = False
                break
            bands[r] = next(iter(nz))
    if horizontal and bands:
        period = len(bands)
        pattern = {r % period: color for r, color in bands.items()}
        return [[pattern[r % period] for _ in range(w)] for r in range(h)]

    # Parallel down-right diagonals define a repeating diagonal color pattern.
    tracks = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in tracks and tracks[d] != color:
                    raise ValueError("mixed colors on a diagonal track")
                tracks[d] = color
    period = len(tracks)
    pattern = {d % period: color for d, color in tracks.items()}
    return [[pattern[(c - r) % period] for c in range(w)] for r in range(h)]
'''
